public class Bottle {
    private final double capacity;
    private double amount;

    public Bottle(double capacity) {
        this.capacity = capacity;
        this.amount = capacity;
    }

    /**
     * Removes the specified amount of liquid from the bottle.
     * Precondition: remove > 0 && remove ≤ amount.
     * If the remaining amount after removal is less than 25 % of the capacity,
     * the bottle is refilled to full capacity.
     *
     * @param remove amount to remove in mL
     * @return the amount of liquid remaining after the update (after possible refill)
     */
    public double updateAmount(double remove) {
        amount -= remove;
        if (amount < 0.25 * capacity) {
            amount = capacity;
        }
        return amount;
    }
}

public class Bottle {
    private double capacity;
    private double amount;

    public Bottle(double capacity) {
        this.capacity = capacity;
        this.amount = capacity;   // bottle starts full
    }

    public double updateAmount(double removal) {
        amount -= removal;                // remove liquid
        if (amount < 0.25 * capacity) {   // below 25% of capacity
            amount = capacity;            // refill bottle
        }
        return amount;                    // amount remaining (or refilled)
    }
}

public class Bottle {
    private final double capacity; // maximum liquid (in mL)
    private double amount;         // current liquid (in mL)

    /** Constructs a Bottle filled to the specified capacity. */
    public Bottle(double capacity) {
        this.capacity = capacity;
        this.amount = capacity;
    }

    /**
     * Removes the specified amount of liquid and refills the bottle
     * if the remaining liquid would be less than 25% of capacity.
     *
     * @param toRemove amount of liquid to remove (in mL);
     *                 precondition: 0 < toRemove <= amount
     * @return the amount of liquid remaining after the update (in mL)
     */
    public double updateAmount(double toRemove) {
        amount -= toRemove;
        if (amount < 0.25 * capacity) {
            amount = capacity; // refill
        }
        return amount;
    }
}

